INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind private IP-Adressen im Internet direkt erreichbar?', 2, '[{"text": "Nein", "correct": true, "because": "Für lokale Netzwerke reserviert"}, {"text": "Ja", "correct": false, "because": "NAT oder VPN nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel privater IP-Adressbereiche?', 3, '[{"text": "Lokale Netzwerke ermöglichen", "correct": true, "because": "Sparen öffentliche IPs"}, {"text": "Globale Routing", "correct": false, "because": "Nur lokal genutzt"}, {"text": "Manuelle Zuweisung", "correct": false, "because": "Automatisierung üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bereiche gehören zu privaten IP-Adressen?', 5, '[{"text": "10.0.0.0/8", "correct": true, "because": "Privater Klasse-A-Bereich"}, {"text": "192.168.0.0/16", "correct": true, "because": "Privater Klasse-C-Bereich"}, {"text": "8.8.8.0/24", "correct": false, "because": "Öffentlich, z. B. Google DNS"}, {"text": "172.15.0.0/16", "correct": false, "because": "Falscher Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) 172.16.0.0/12 ist privat. b) Private IPs sind global eindeutig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) nicht global eindeutig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Nutzung privater IP-Adressen?', 4, '[{"text": "Subnetzmaske", "correct": false, "because": "Definiert Netzwerk"}, {"text": "NAT-Konfiguration", "correct": false, "because": "Ermöglicht Internetzugriff"}, {"text": "Farbcodierung", "correct": true, "because": "Irrelevant für IPs"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob 192.168.1.1 eine private IP ist?', 2, '[{"text": "Ja", "correct": true, "because": "Teil des 192.168.0.0/16-Bereichs"}, {"text": "Nein", "correct": false, "because": "Privat reserviert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Bereich wird oft für Heimnetzwerke genutzt?', 3, '[{"text": "192.168.0.0/16", "correct": true, "because": "Typisch für Router"}, {"text": "10.10.0.0/16", "correct": false, "because": "Weniger üblich"}, {"text": "172.32.0.0/12", "correct": false, "because": "Seltener in Heimnetzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologien nutzen private IP-Adressen?', 5, '[{"text": "NAT", "correct": true, "because": "Verknüpft private mit öffentlichen IPs"}, {"text": "VPN", "correct": true, "because": "Sichere lokale Verbindungen"}, {"text": "Bluetooth", "correct": false, "because": "Kein IP-Protokoll"}, {"text": "USB", "correct": false, "because": "Keine Netzwerktechnik"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Private IPs sparen öffentliche Adressen. b) Sie sind direkt im Internet routbar. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) benötigt NAT"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für private IP-Adressen?', 4, '[{"text": "Router", "correct": false, "because": "Verwaltet Adressen"}, {"text": "Subnetzmaske", "correct": false, "because": "Definiert Netzwerk"}, {"text": "Grafische Oberfläche", "correct": true, "because": "Nicht für Adressen nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann eine private IP mehrfach genutzt werden?', 2, '[{"text": "Ja", "correct": true, "because": "In verschiedenen Netzen"}, {"text": "Nein", "correct": false, "because": "Nicht global eindeutig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können bei privaten IPs auftreten?', 4, '[{"text": "Adresskonflikte", "correct": true, "because": "Gleiche IPs im Netz"}, {"text": "NAT-Komplexität", "correct": true, "because": "Konfiguration aufwendig"}, {"text": "Hohe Auflösung", "correct": false, "because": "Kein Netzwerkproblem"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass private IPs immer sicher sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Sicherheit hängt von Konfiguration ab"}, {"text": "Ja", "correct": false, "because": "Nicht automatisch sicher"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Nutzung privater IPs?', 3, '[{"text": "Korrekte Subnetzplanung", "correct": true, "because": "Vermeidet Konflikte"}, {"text": "Maximale Adressanzahl", "correct": false, "because": "Effizienz wichtiger"}, {"text": "Manuelle Zuweisung", "correct": false, "because": "DHCP effizienter"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) 10.0.0.0/8 ist privat. b) Private IPs sind öffentlich routbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) benötigt NAT"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten private IP-Adressbereiche?', 5, '[{"text": "Kosteneffizienz", "correct": true, "because": "Sparen öffentliche IPs"}, {"text": "Lokale Sicherheit", "correct": true, "because": "Nicht direkt erreichbar"}, {"text": "Globale Eindeutigkeit", "correct": false, "because": "Nicht erforderlich"}, {"text": "Grafische Darstellung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei privaten IP-Adressen unwichtig?', 3, '[{"text": "Netzwerksegmentierung", "correct": false, "because": "Optimiert Verwaltung"}, {"text": "IP-Konfliktvermeidung", "correct": false, "because": "Sichert Kommunikation"}, {"text": "Musikwiedergabe", "correct": true, "because": "Kein Netzwerkfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob private IPs für große Unternehmen geeignet sind?', 2, '[{"text": "Ja", "correct": true, "because": "10.0.0.0/8 bietet viele Adressen"}, {"text": "Nein", "correct": false, "because": "Skalierbar für alle Größen"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Erfordern private IPs immer NAT für Internetzugriff?', 3, '[{"text": "Ja", "correct": true, "because": "Öffentliche IP nötig"}, {"text": "Nein", "correct": false, "because": "NAT üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu privaten IP-Adressen?', 4, '[{"text": "Heimnetzwerk mit WLAN-Router", "correct": true, "because": "Nutzt 192.168.0.0/16"}, {"text": "Öffentlicher Webserver", "correct": false, "because": "Benötigt öffentliche IP"}, {"text": "Musikwiedergabe", "correct": false, "because": "Keine Netzwerkaufgabe"}]');
